-- Scoped P-capable reuse primitives. Store owns signed complete-source/target/ref protocol.
-- No schema change, arbitrary inactive selection, exact-path relaxation or history rewrite.

-- name: ListReuseTargetSeasons :many
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
)
SELECT season.id,season.code,season.name,season.starts_on,season.ends_on FROM seasons season CROSS JOIN training_groups g CROSS JOIN actor WHERE g.id=sqlc.arg(group_id)::uuid AND (actor.administrator OR EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((g.programme_id IS NOT NULL AND grant_row.programme_id=g.programme_id) OR (g.team_id IS NOT NULL AND grant_row.team_id=g.team_id)))) AND (g.team_id IS NULL OR EXISTS(SELECT 1 FROM teams team WHERE team.id=g.team_id AND team.season_id=season.id)) ORDER BY season.starts_on DESC,season.id LIMIT 101;

-- name: GetReusePlan :one
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
), scoped_plans AS NOT MATERIALIZED (SELECT plan.* FROM training_plans plan JOIN training_groups g ON g.id=plan.training_group_id JOIN seasons season ON season.id=plan.season_id CROSS JOIN actor WHERE (actor.administrator OR EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((g.programme_id IS NOT NULL AND grant_row.programme_id=g.programme_id) OR (g.team_id IS NOT NULL AND grant_row.team_id=g.team_id)))))
SELECT plan.*,g.name AS group_name,g.updated_at AS group_updated_at,season.code AS season_code,season.name AS season_name,season.starts_on AS season_starts_on,season.ends_on AS season_ends_on FROM scoped_plans plan JOIN training_groups g ON g.id=plan.training_group_id JOIN seasons season ON season.id=plan.season_id WHERE plan.id=sqlc.arg(plan_id)::uuid;

-- name: ListReuseSourceSessions :many
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
), scoped_plans AS NOT MATERIALIZED (SELECT plan.* FROM training_plans plan JOIN training_groups g ON g.id=plan.training_group_id JOIN seasons season ON season.id=plan.season_id CROSS JOIN actor WHERE (actor.administrator OR EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((g.programme_id IS NOT NULL AND grant_row.programme_id=g.programme_id) OR (g.team_id IS NOT NULL AND grant_row.team_id=g.team_id)))))
SELECT session.*,public.training_session_local_date(session.scheduled_on,session.starts_at) AS session_on FROM training_sessions session JOIN scoped_plans plan ON plan.id=session.plan_id WHERE plan.id=sqlc.arg(plan_id)::uuid AND session.status='ACTIVE' AND (sqlc.narg(source_day)::date IS NULL OR public.training_session_local_date(session.scheduled_on,session.starts_at)=sqlc.narg(source_day)::date) AND NOT session.id=ANY(COALESCE(sqlc.arg(own_destination_session_ids)::uuid[],'{}'::uuid[])) AND cardinality(COALESCE(sqlc.arg(own_destination_session_ids)::uuid[],'{}'::uuid[]))<=64 AND cardinality(COALESCE(sqlc.arg(own_destination_session_ids)::uuid[],'{}'::uuid[]))=(SELECT count(DISTINCT id) FROM unnest(COALESCE(sqlc.arg(own_destination_session_ids)::uuid[],'{}'::uuid[])) own(id)) ORDER BY public.training_session_local_date(session.scheduled_on,session.starts_at),session.starts_at NULLS LAST,session.id LIMIT 65;

-- name: GetReuseTargetContext :one
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
), target AS (SELECT g.id AS group_id,g.programme_id,g.team_id,g.name AS group_name,g.updated_at AS group_updated_at,season.id AS season_id,season.code AS season_code,season.name AS season_name,season.starts_on AS season_starts_on,season.ends_on AS season_ends_on,sqlc.arg(week_start)::date AS week_start FROM training_groups g CROSS JOIN seasons season CROSS JOIN actor WHERE g.id=sqlc.arg(group_id)::uuid AND season.id=sqlc.arg(season_id)::uuid AND (actor.administrator OR EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((g.programme_id IS NOT NULL AND grant_row.programme_id=g.programme_id) OR (g.team_id IS NOT NULL AND grant_row.team_id=g.team_id)))) AND extract(isodow FROM sqlc.arg(week_start)::date)=1 AND sqlc.arg(week_start)::date BETWEEN season.starts_on AND season.ends_on AND (g.team_id IS NULL OR EXISTS(SELECT 1 FROM teams team WHERE team.id=g.team_id AND team.season_id=season.id)))
SELECT target.*,plan.id AS existing_plan_id,plan.updated_at AS existing_plan_updated_at FROM target target LEFT JOIN training_plans plan ON plan.training_group_id=target.group_id AND plan.week_start=target.week_start WHERE plan.id IS NULL OR plan.season_id=target.season_id;

-- name: LockReuseTargetContext :one
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
), target AS (SELECT g.id AS group_id,g.programme_id,g.team_id,g.name AS group_name,g.updated_at AS group_updated_at,season.id AS season_id,season.code AS season_code,season.name AS season_name,season.starts_on AS season_starts_on,season.ends_on AS season_ends_on,sqlc.arg(week_start)::date AS week_start FROM training_groups g CROSS JOIN seasons season CROSS JOIN actor WHERE g.id=sqlc.arg(group_id)::uuid AND season.id=sqlc.arg(season_id)::uuid AND (actor.administrator OR EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((g.programme_id IS NOT NULL AND grant_row.programme_id=g.programme_id) OR (g.team_id IS NOT NULL AND grant_row.team_id=g.team_id)))) AND extract(isodow FROM sqlc.arg(week_start)::date)=1 AND sqlc.arg(week_start)::date BETWEEN season.starts_on AND season.ends_on AND (g.team_id IS NULL OR EXISTS(SELECT 1 FROM teams team WHERE team.id=g.team_id AND team.season_id=season.id))), locked_target AS MATERIALIZED (SELECT target.* FROM target JOIN training_groups g ON g.id=target.group_id JOIN seasons season ON season.id=target.season_id WHERE target.team_id IS NULL OR EXISTS(SELECT 1 FROM teams team WHERE team.id=target.team_id AND team.season_id=target.season_id FOR SHARE OF team NOWAIT) FOR SHARE OF g,season NOWAIT)
SELECT target.*,plan.id AS existing_plan_id,plan.updated_at AS existing_plan_updated_at FROM locked_target target LEFT JOIN training_plans plan ON plan.training_group_id=target.group_id AND plan.week_start=target.week_start WHERE plan.id IS NULL OR plan.season_id=target.season_id;

-- name: CreateReuseWeek :one
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
), target AS (SELECT g.id AS group_id,g.programme_id,g.team_id,g.name AS group_name,g.updated_at AS group_updated_at,season.id AS season_id,season.code AS season_code,season.name AS season_name,season.starts_on AS season_starts_on,season.ends_on AS season_ends_on,sqlc.arg(week_start)::date AS week_start FROM training_groups g CROSS JOIN seasons season CROSS JOIN actor WHERE g.id=sqlc.arg(group_id)::uuid AND season.id=sqlc.arg(season_id)::uuid AND (actor.administrator OR EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((g.programme_id IS NOT NULL AND grant_row.programme_id=g.programme_id) OR (g.team_id IS NOT NULL AND grant_row.team_id=g.team_id)))) AND extract(isodow FROM sqlc.arg(week_start)::date)=1 AND sqlc.arg(week_start)::date BETWEEN season.starts_on AND season.ends_on AND (g.team_id IS NULL OR EXISTS(SELECT 1 FROM teams team WHERE team.id=g.team_id AND team.season_id=season.id)))
INSERT INTO training_plans(id,title,description,programme_id,team_id,training_group_id,season_id,week_start,planned_load_percentage,created_by_id) SELECT sqlc.arg(id)::uuid,sqlc.arg(title)::text,sqlc.arg(description)::text,target.programme_id,target.team_id,target.group_id,target.season_id,target.week_start,sqlc.narg(planned_load_percentage)::smallint,sqlc.arg(actor_id)::uuid FROM target RETURNING *;

-- name: ListReuseRoutines :many
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
), visible_routines AS NOT MATERIALIZED (SELECT routine.* FROM training_routines routine CROSS JOIN actor WHERE (routine.owner_user_id=actor.id OR actor.administrator OR (routine.visibility='SHARED' AND EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((routine.programme_id IS NOT NULL AND grant_row.programme_id=routine.programme_id) OR (routine.team_id IS NOT NULL AND grant_row.team_id=routine.team_id))))))
SELECT routine.id,routine.name,routine.description,routine.kind,routine.visibility,routine.programme_id,routine.team_id,routine.modality,routine.objective,routine.method,routine.tags,routine.source_id,routine.source_updated_at,routine.created_at,routine.updated_at FROM visible_routines routine WHERE (sqlc.arg(query)::text='' OR routine.name ILIKE '%'||replace(replace(replace(sqlc.arg(query)::text,chr(92),chr(92)||chr(92)),'%',chr(92)||'%'),'_',chr(92)||'_')||'%' ESCAPE E'\\' OR routine.description ILIKE '%'||replace(replace(replace(sqlc.arg(query)::text,chr(92),chr(92)||chr(92)),'%',chr(92)||'%'),'_',chr(92)||'_')||'%' ESCAPE E'\\' OR routine.method ILIKE '%'||replace(replace(replace(sqlc.arg(query)::text,chr(92),chr(92)||chr(92)),'%',chr(92)||'%'),'_',chr(92)||'_')||'%' ESCAPE E'\\') AND (sqlc.arg(modality)::text='' OR routine.modality::text=sqlc.arg(modality)::text) AND (sqlc.arg(objective)::text='' OR routine.objective::text=sqlc.arg(objective)::text) AND (sqlc.arg(tag)::text='' OR EXISTS(SELECT 1 FROM unnest(routine.tags) tag WHERE lower(tag)=lower(sqlc.arg(tag)::text))) AND sqlc.arg(row_offset)::integer>=0 ORDER BY routine.updated_at DESC,routine.id LIMIT 21 OFFSET sqlc.arg(row_offset)::integer;

-- name: GetReuseRoutine :one
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
), visible_routines AS NOT MATERIALIZED (SELECT routine.* FROM training_routines routine CROSS JOIN actor WHERE (routine.owner_user_id=actor.id OR actor.administrator OR (routine.visibility='SHARED' AND EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((routine.programme_id IS NOT NULL AND grant_row.programme_id=routine.programme_id) OR (routine.team_id IS NOT NULL AND grant_row.team_id=routine.team_id))))))
SELECT routine.id,routine.name,routine.description,routine.kind,routine.visibility,routine.owner_user_id,routine.programme_id,routine.team_id,routine.modality,routine.objective,routine.method,routine.tags,routine.source_id,routine.source_updated_at,CASE WHEN octet_length(routine.snapshot::text)<=1048576 THEN routine.snapshot ELSE NULL::jsonb END AS snapshot,routine.created_at,routine.updated_at,octet_length(routine.snapshot::text)::bigint AS snapshot_bytes,(octet_length(routine.snapshot::text)>1048576)::boolean AS overflow FROM training_routines routine JOIN visible_routines visible ON visible.id=routine.id WHERE routine.id=sqlc.arg(routine_id)::uuid;

-- name: LockReuseRoutine :one
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
), visible_routines AS NOT MATERIALIZED (SELECT routine.* FROM training_routines routine CROSS JOIN actor WHERE (routine.owner_user_id=actor.id OR actor.administrator OR (routine.visibility='SHARED' AND EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((routine.programme_id IS NOT NULL AND grant_row.programme_id=routine.programme_id) OR (routine.team_id IS NOT NULL AND grant_row.team_id=routine.team_id))))))
SELECT routine.id,routine.name,routine.description,routine.kind,routine.visibility,routine.owner_user_id,routine.programme_id,routine.team_id,routine.modality,routine.objective,routine.method,routine.tags,routine.source_id,routine.source_updated_at,CASE WHEN octet_length(routine.snapshot::text)<=1048576 THEN routine.snapshot ELSE NULL::jsonb END AS snapshot,routine.created_at,routine.updated_at,octet_length(routine.snapshot::text)::bigint AS snapshot_bytes,(octet_length(routine.snapshot::text)>1048576)::boolean AS overflow FROM training_routines routine JOIN visible_routines visible ON visible.id=routine.id WHERE routine.id=sqlc.arg(routine_id)::uuid FOR SHARE OF routine NOWAIT;

-- name: ListReusePinnedProfiles :many
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
), scoped_plans AS NOT MATERIALIZED (SELECT plan.* FROM training_plans plan JOIN training_groups g ON g.id=plan.training_group_id JOIN seasons season ON season.id=plan.season_id CROSS JOIN actor WHERE (actor.administrator OR EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((g.programme_id IS NOT NULL AND grant_row.programme_id=g.programme_id) OR (g.team_id IS NOT NULL AND grant_row.team_id=g.team_id))))), visible_routines AS NOT MATERIALIZED (SELECT routine.* FROM training_routines routine CROSS JOIN actor WHERE (routine.owner_user_id=actor.id OR actor.administrator OR (routine.visibility='SHARED' AND EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((routine.programme_id IS NOT NULL AND grant_row.programme_id=routine.programme_id) OR (routine.team_id IS NOT NULL AND grant_row.team_id=routine.team_id)))))), origin AS (SELECT sqlc.narg(native_source_plan_id)::uuid AS plan_id,COALESCE(sqlc.arg(native_source_block_ids)::uuid[],'{}'::uuid[]) AS block_ids,sqlc.narg(routine_id)::uuid AS routine_id), native_blocks AS MATERIALIZED (
 SELECT block.id,water.intensity_profile_id FROM water_block_prescriptions water JOIN training_segment_blocks block ON block.id=water.block_id JOIN training_session_segments segment ON segment.id=block.segment_id JOIN training_sessions session ON session.id=segment.session_id JOIN scoped_plans plan ON plan.id=session.plan_id CROSS JOIN origin WHERE plan.id=origin.plan_id AND block.id=ANY(origin.block_ids) AND session.status='ACTIVE' AND cardinality(origin.block_ids)<=2048
), routine_source AS MATERIALIZED (SELECT routine.* FROM visible_routines routine CROSS JOIN origin WHERE routine.id=origin.routine_id AND octet_length(routine.snapshot::text)<=1048576), routine_blocks AS MATERIALIZED (
 SELECT block FROM (
 SELECT routine.snapshot AS block FROM routine_source routine WHERE routine.kind='BLOCK'
 UNION ALL
 SELECT block.value FROM routine_source routine CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(routine.snapshot->'blocks')='array' THEN routine.snapshot->'blocks' ELSE '[]'::jsonb END) block WHERE routine.kind='SEGMENT'
 UNION ALL
 SELECT block.value FROM routine_source routine CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(routine.snapshot->'segments')='array' THEN routine.snapshot->'segments' ELSE '[]'::jsonb END) segment CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(segment.value->'blocks')='array' THEN segment.value->'blocks' ELSE '[]'::jsonb END) block WHERE routine.kind='SESSION'
 ) all_blocks LIMIT 33
), origin_valid AS (
 SELECT 1 FROM origin WHERE (origin.plan_id IS NOT NULL AND origin.routine_id IS NULL AND EXISTS(SELECT 1 FROM scoped_plans p WHERE p.id=origin.plan_id) AND cardinality(origin.block_ids)<=2048 AND cardinality(origin.block_ids)=(SELECT count(DISTINCT id) FROM unnest(origin.block_ids) selected(id)) AND cardinality(origin.block_ids)=(SELECT count(*) FROM native_blocks))
 OR (origin.plan_id IS NULL AND origin.routine_id IS NOT NULL AND cardinality(origin.block_ids)=0 AND EXISTS(SELECT 1 FROM routine_source) AND (SELECT count(*) FROM routine_blocks)<=32)
), pin_ids AS MATERIALIZED (
 SELECT DISTINCT profile_id FROM (
 SELECT intensity_profile_id AS profile_id FROM native_blocks
 UNION ALL SELECT NULLIF(block->'water'->>'intensity_profile_id','')::uuid FROM routine_blocks
 ) ids WHERE profile_id IS NOT NULL
), pin_profiles AS (SELECT profile.* FROM water_intensity_profiles profile JOIN pin_ids pin ON pin.profile_id=profile.id CROSS JOIN origin_valid WHERE (SELECT count(*) FROM pin_ids)<=32 AND (SELECT count(*) FROM pin_ids)=(SELECT count(*) FROM water_intensity_profiles p JOIN pin_ids pin ON pin.profile_id=p.id))
SELECT profile.* FROM water_intensity_profiles profile JOIN pin_profiles pin ON pin.id=profile.id ORDER BY profile.id;

