), routine_source AS MATERIALIZED (SELECT routine.* FROM visible_routines routine CROSS JOIN origin WHERE routine.id=origin.routine_id AND octet_length(routine.snapshot::text)<=1048576), routine_blocks AS MATERIALIZED (
 SELECT block FROM (
 SELECT routine.snapshot AS block FROM routine_source routine WHERE routine.kind='BLOCK'
 UNION ALL
 SELECT block.value FROM routine_source routine CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(routine.snapshot->'blocks')='array' THEN routine.snapshot->'blocks' ELSE '[]'::jsonb END) block WHERE routine.kind='SEGMENT'
 UNION ALL
 SELECT block.value FROM routine_source routine CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(routine.snapshot->'segments')='array' THEN routine.snapshot->'segments' ELSE '[]'::jsonb END) segment CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(segment.value->'blocks')='array' THEN segment.value->'blocks' ELSE '[]'::jsonb END) block WHERE routine.kind='SESSION'
 ) all_blocks LIMIT 33
), origin_valid AS (
 SELECT 1 FROM origin WHERE (origin.plan_id IS NOT NULL AND origin.routine_id IS NULL AND EXISTS(SELECT 1 FROM scoped_plans p WHERE p.id=origin.plan_id) AND cardinality(origin.block_ids)<=2048 AND cardinality(origin.block_ids)=(SELECT count(DISTINCT id) FROM unnest(origin.block_ids) selected(id)) AND cardinality(origin.block_ids)=(SELECT count(*) FROM native_blocks))
 OR (origin.plan_id IS NULL AND origin.routine_id IS NOT NULL AND cardinality(origin.block_ids)=0 AND EXISTS(SELECT 1 FROM routine_source) AND (SELECT count(*) FROM routine_blocks)<=32)
), pin_ids AS MATERIALIZED (
 SELECT DISTINCT profile_id FROM (
 SELECT intensity_profile_id AS profile_id FROM native_blocks
 UNION ALL SELECT NULLIF(block->'water'->>'intensity_profile_id','')::uuid FROM routine_blocks
 ) ids WHERE profile_id IS NOT NULL
), pin_profiles AS (SELECT profile.* FROM water_intensity_profiles profile JOIN pin_ids pin ON pin.profile_id=profile.id CROSS JOIN origin_valid WHERE (SELECT count(*) FROM pin_ids)<=32 AND (SELECT count(*) FROM pin_ids)=(SELECT count(*) FROM water_intensity_profiles p JOIN pin_ids pin ON pin.profile_id=p.id))
SELECT profile.* FROM water_intensity_profiles profile JOIN pin_profiles pin ON pin.id=profile.id ORDER BY profile.id FOR SHARE OF profile NOWAIT;

-- name: ListReusePinnedZones :many
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
), scoped_plans AS NOT MATERIALIZED (SELECT plan.* FROM training_plans plan JOIN training_groups g ON g.id=plan.training_group_id JOIN seasons season ON season.id=plan.season_id CROSS JOIN actor WHERE (actor.administrator OR EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((g.programme_id IS NOT NULL AND grant_row.programme_id=g.programme_id) OR (g.team_id IS NOT NULL AND grant_row.team_id=g.team_id))))), visible_routines AS NOT MATERIALIZED (SELECT routine.* FROM training_routines routine CROSS JOIN actor WHERE (routine.owner_user_id=actor.id OR actor.administrator OR (routine.visibility='SHARED' AND EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((routine.programme_id IS NOT NULL AND grant_row.programme_id=routine.programme_id) OR (routine.team_id IS NOT NULL AND grant_row.team_id=routine.team_id)))))), origin AS (SELECT sqlc.narg(native_source_plan_id)::uuid AS plan_id,COALESCE(sqlc.arg(native_source_block_ids)::uuid[],'{}'::uuid[]) AS block_ids,sqlc.narg(routine_id)::uuid AS routine_id), native_blocks AS MATERIALIZED (
 SELECT block.id,water.intensity_profile_id FROM water_block_prescriptions water JOIN training_segment_blocks block ON block.id=water.block_id JOIN training_session_segments segment ON segment.id=block.segment_id JOIN training_sessions session ON session.id=segment.session_id JOIN scoped_plans plan ON plan.id=session.plan_id CROSS JOIN origin WHERE plan.id=origin.plan_id AND block.id=ANY(origin.block_ids) AND session.status='ACTIVE' AND cardinality(origin.block_ids)<=2048
), routine_source AS MATERIALIZED (SELECT routine.* FROM visible_routines routine CROSS JOIN origin WHERE routine.id=origin.routine_id AND octet_length(routine.snapshot::text)<=1048576), routine_blocks AS MATERIALIZED (
 SELECT block FROM (
 SELECT routine.snapshot AS block FROM routine_source routine WHERE routine.kind='BLOCK'
 UNION ALL
 SELECT block.value FROM routine_source routine CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(routine.snapshot->'blocks')='array' THEN routine.snapshot->'blocks' ELSE '[]'::jsonb END) block WHERE routine.kind='SEGMENT'
 UNION ALL
 SELECT block.value FROM routine_source routine CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(routine.snapshot->'segments')='array' THEN routine.snapshot->'segments' ELSE '[]'::jsonb END) segment CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(segment.value->'blocks')='array' THEN segment.value->'blocks' ELSE '[]'::jsonb END) block WHERE routine.kind='SESSION'
 ) all_blocks LIMIT 33
), origin_valid AS (
 SELECT 1 FROM origin WHERE (origin.plan_id IS NOT NULL AND origin.routine_id IS NULL AND EXISTS(SELECT 1 FROM scoped_plans p WHERE p.id=origin.plan_id) AND cardinality(origin.block_ids)<=2048 AND cardinality(origin.block_ids)=(SELECT count(DISTINCT id) FROM unnest(origin.block_ids) selected(id)) AND cardinality(origin.block_ids)=(SELECT count(*) FROM native_blocks))
 OR (origin.plan_id IS NULL AND origin.routine_id IS NOT NULL AND cardinality(origin.block_ids)=0 AND EXISTS(SELECT 1 FROM routine_source) AND (SELECT count(*) FROM routine_blocks)<=32)
), pin_ids AS MATERIALIZED (
 SELECT DISTINCT profile_id FROM (
 SELECT intensity_profile_id AS profile_id FROM native_blocks
 UNION ALL SELECT NULLIF(block->'water'->>'intensity_profile_id','')::uuid FROM routine_blocks
 ) ids WHERE profile_id IS NOT NULL
), pin_profiles AS (SELECT profile.* FROM water_intensity_profiles profile JOIN pin_ids pin ON pin.profile_id=profile.id CROSS JOIN origin_valid WHERE (SELECT count(*) FROM pin_ids)<=32 AND (SELECT count(*) FROM pin_ids)=(SELECT count(*) FROM water_intensity_profiles p JOIN pin_ids pin ON pin.profile_id=p.id))
SELECT zone.* FROM water_intensity_zones zone JOIN pin_profiles profile ON profile.id=zone.profile_id ORDER BY zone.profile_id,zone.position,zone.id LIMIT 257;

-- name: InsertCopiedWorkoutSession :one
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
), scoped_plans AS NOT MATERIALIZED (SELECT plan.* FROM training_plans plan JOIN training_groups g ON g.id=plan.training_group_id JOIN seasons season ON season.id=plan.season_id CROSS JOIN actor WHERE (actor.administrator OR EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((g.programme_id IS NOT NULL AND grant_row.programme_id=g.programme_id) OR (g.team_id IS NOT NULL AND grant_row.team_id=g.team_id)))))
INSERT INTO training_sessions(id,plan_id,title,description,starts_at,ends_at,modality_id,entry_kind,created_by_id,schedule_precision,scheduled_on,day_band) SELECT sqlc.arg(id)::uuid,plan.id,sqlc.arg(title)::text,sqlc.arg(description)::text,sqlc.narg(starts_at)::timestamptz,sqlc.narg(ends_at)::timestamptz,sqlc.narg(modality_id)::uuid,sqlc.arg(entry_kind)::training_entry_kind,sqlc.arg(actor_id)::uuid,sqlc.arg(schedule_precision)::text,sqlc.narg(scheduled_on)::date,sqlc.narg(day_band)::text FROM scoped_plans plan WHERE plan.id=sqlc.arg(target_plan_id)::uuid AND plan.updated_at=sqlc.arg(expected_plan_updated_at)::timestamptz AND sqlc.arg(target_day)::date>=plan.week_start AND sqlc.arg(target_day)::date<plan.week_start+7 AND public.training_session_local_date(sqlc.narg(scheduled_on)::date,sqlc.narg(starts_at)::timestamptz)=sqlc.arg(target_day)::date RETURNING *;

-- name: InsertCopiedWaterPrescription :one
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
), scoped_plans AS NOT MATERIALIZED (SELECT plan.* FROM training_plans plan JOIN training_groups g ON g.id=plan.training_group_id JOIN seasons season ON season.id=plan.season_id CROSS JOIN actor WHERE (actor.administrator OR EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((g.programme_id IS NOT NULL AND grant_row.programme_id=g.programme_id) OR (g.team_id IS NOT NULL AND grant_row.team_id=g.team_id))))), visible_routines AS NOT MATERIALIZED (SELECT routine.* FROM training_routines routine CROSS JOIN actor WHERE (routine.owner_user_id=actor.id OR actor.administrator OR (routine.visibility='SHARED' AND EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((routine.programme_id IS NOT NULL AND grant_row.programme_id=routine.programme_id) OR (routine.team_id IS NOT NULL AND grant_row.team_id=routine.team_id)))))), origin AS (SELECT sqlc.narg(native_source_plan_id)::uuid AS plan_id,sqlc.narg(native_source_block_id)::uuid AS block_id,sqlc.narg(routine_id)::uuid AS routine_id,COALESCE(sqlc.arg(routine_path)::integer[],'{}'::integer[]) AS path), native_water AS (
 SELECT water.method,water.intensity_profile_id,water.target_distance_metres,water.target_distance_certainty FROM water_block_prescriptions water JOIN training_segment_blocks block ON block.id=water.block_id JOIN training_session_segments segment ON segment.id=block.segment_id JOIN training_sessions session ON session.id=segment.session_id JOIN scoped_plans plan ON plan.id=session.plan_id CROSS JOIN origin WHERE plan.id=origin.plan_id AND block.id=origin.block_id AND session.status='ACTIVE' AND origin.routine_id IS NULL AND cardinality(origin.path)=0
), routine_water AS (
 SELECT CASE WHEN routine.kind='BLOCK' AND cardinality(origin.path)=0 THEN routine.snapshot->'water'
 WHEN routine.kind='SEGMENT' AND cardinality(origin.path)=1 AND origin.path[1] BETWEEN 0 AND 31 THEN routine.snapshot->'blocks'->(origin.path[1])->'water'
 WHEN routine.kind='SESSION' AND cardinality(origin.path)=2 AND origin.path[1] BETWEEN 0 AND 7 AND origin.path[2] BETWEEN 0 AND 31 THEN routine.snapshot->'segments'->(origin.path[1])->'blocks'->(origin.path[2])->'water' ELSE NULL::jsonb END AS water
 FROM visible_routines routine CROSS JOIN origin WHERE routine.id=origin.routine_id AND origin.plan_id IS NULL AND origin.block_id IS NULL AND octet_length(routine.snapshot::text)<=1048576
), source_water AS (
 SELECT * FROM native_water UNION ALL
 SELECT (water->>'method')::water_work_method,NULLIF(water->>'intensity_profile_id','')::uuid,NULLIF(water->>'target_distance_metres','')::integer,NULLIF(water->>'target_distance_certainty','')::training_measure_certainty FROM routine_water WHERE jsonb_typeof(water)='object'
)
INSERT INTO water_block_prescriptions(block_id,method,intensity_profile_id,target_distance_metres,target_distance_certainty) SELECT block.id,water.method,water.intensity_profile_id,water.target_distance_metres,water.target_distance_certainty FROM training_segment_blocks block JOIN training_session_segments segment ON segment.id=block.segment_id JOIN training_sessions session ON session.id=segment.session_id JOIN scoped_plans plan ON plan.id=session.plan_id CROSS JOIN source_water water WHERE plan.id=sqlc.arg(target_plan_id)::uuid AND session.id=sqlc.arg(target_session_id)::uuid AND segment.id=sqlc.arg(target_segment_id)::uuid AND block.id=sqlc.arg(target_block_id)::uuid AND segment.modality='WATER' AND session.status='ACTIVE' AND session.entry_kind IN ('TRAINING','COMPETITION') RETURNING *;

-- name: InsertReuseCopyEvent :one
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
), scoped_plans AS NOT MATERIALIZED (SELECT plan.* FROM training_plans plan JOIN training_groups g ON g.id=plan.training_group_id JOIN seasons season ON season.id=plan.season_id CROSS JOIN actor WHERE (actor.administrator OR EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((g.programme_id IS NOT NULL AND grant_row.programme_id=g.programme_id) OR (g.team_id IS NOT NULL AND grant_row.team_id=g.team_id))))), visible_routines AS NOT MATERIALIZED (SELECT routine.* FROM training_routines routine CROSS JOIN actor WHERE (routine.owner_user_id=actor.id OR actor.administrator OR (routine.visibility='SHARED' AND EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((routine.programme_id IS NOT NULL AND grant_row.programme_id=routine.programme_id) OR (routine.team_id IS NOT NULL AND grant_row.team_id=routine.team_id)))))), objects AS NOT MATERIALIZED (SELECT 'WEEK'::text AS kind,plan.id,plan.id AS plan_id,plan.updated_at FROM scoped_plans plan UNION ALL SELECT 'SESSION',s.id,s.plan_id,s.updated_at FROM training_sessions s JOIN scoped_plans p ON p.id=s.plan_id UNION ALL SELECT 'SEGMENT',a.id,s.plan_id,a.updated_at FROM training_session_segments a JOIN training_sessions s ON s.id=a.session_id JOIN scoped_plans p ON p.id=s.plan_id UNION ALL SELECT 'BLOCK',b.id,s.plan_id,b.updated_at FROM training_segment_blocks b JOIN training_session_segments a ON a.id=b.segment_id JOIN training_sessions s ON s.id=a.session_id JOIN scoped_plans p ON p.id=s.plan_id), input AS (SELECT sqlc.arg(id)::uuid AS id,sqlc.arg(source_kind)::text AS source_kind,sqlc.arg(source_id)::uuid AS source_id,sqlc.arg(source_updated_at)::timestamptz AS source_updated_at,sqlc.arg(destination_kind)::text AS destination_kind,sqlc.arg(destination_id)::uuid AS destination_id)
INSERT INTO training_copy_events(id,source_kind,source_id,source_updated_at,destination_kind,destination_id,copied_by_id) SELECT input.id,input.source_kind,input.source_id,input.source_updated_at,input.destination_kind,input.destination_id,sqlc.arg(actor_id)::uuid FROM input WHERE ((input.source_kind='WEEK' AND input.destination_kind IN ('WEEK','SESSION')) OR (input.source_kind IN ('DAY','SESSION') AND input.destination_kind='SESSION') OR (input.source_kind IN ('BLOCK','SEGMENT') AND input.destination_kind=input.source_kind) OR (input.source_kind='ROUTINE' AND EXISTS(SELECT 1 FROM visible_routines r WHERE r.id=input.source_id AND r.kind::text=input.destination_kind))) AND EXISTS(SELECT 1 FROM objects destination WHERE destination.id=input.destination_id AND destination.kind=input.destination_kind AND destination.plan_id=sqlc.arg(target_plan_id)::uuid) AND ((sqlc.narg(source_plan_id)::uuid IS NOT NULL AND sqlc.narg(routine_id)::uuid IS NULL AND EXISTS(SELECT 1 FROM objects source WHERE source.plan_id=sqlc.narg(source_plan_id)::uuid AND source.id=input.source_id AND source.kind=CASE WHEN input.source_kind IN ('DAY','WEEK') AND input.destination_kind='SESSION' THEN 'SESSION' ELSE input.source_kind END AND source.updated_at=input.source_updated_at)) OR (sqlc.narg(source_plan_id)::uuid IS NULL AND sqlc.narg(routine_id)::uuid IS NOT NULL AND input.source_kind='ROUTINE' AND EXISTS(SELECT 1 FROM visible_routines routine WHERE routine.id=sqlc.narg(routine_id)::uuid AND routine.id=input.source_id AND routine.updated_at=input.source_updated_at))) RETURNING *;

-- name: GetReuseCopyEventsByIDs :many
WITH actor AS (
 SELECT u.id,EXISTS(SELECT 1 FROM user_platform_roles r JOIN platform_roles p ON p.id=r.role_id WHERE r.user_id=u.id AND p.code='ADMIN') AS administrator
 FROM users u WHERE u.id=sqlc.arg(actor_id)::uuid AND u.is_active AND u.erased_at IS NULL AND NOT u.is_dependent
 AND u.date_of_birth<=((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '18 years')::date
), scoped_plans AS NOT MATERIALIZED (SELECT plan.* FROM training_plans plan JOIN training_groups g ON g.id=plan.training_group_id JOIN seasons season ON season.id=plan.season_id CROSS JOIN actor WHERE (actor.administrator OR EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((g.programme_id IS NOT NULL AND grant_row.programme_id=g.programme_id) OR (g.team_id IS NOT NULL AND grant_row.team_id=g.team_id))))), visible_routines AS NOT MATERIALIZED (SELECT routine.* FROM training_routines routine CROSS JOIN actor WHERE (routine.owner_user_id=actor.id OR actor.administrator OR (routine.visibility='SHARED' AND EXISTS(SELECT 1 FROM staff_grants grant_row WHERE grant_row.user_id=actor.id AND grant_row.capability='COACH' AND grant_row.revoked_at IS NULL AND ((routine.programme_id IS NOT NULL AND grant_row.programme_id=routine.programme_id) OR (routine.team_id IS NOT NULL AND grant_row.team_id=routine.team_id)))))), objects AS NOT MATERIALIZED (SELECT 'WEEK'::text AS kind,plan.id,plan.id AS plan_id,plan.updated_at FROM scoped_plans plan UNION ALL SELECT 'SESSION',s.id,s.plan_id,s.updated_at FROM training_sessions s JOIN scoped_plans p ON p.id=s.plan_id UNION ALL SELECT 'SEGMENT',a.id,s.plan_id,a.updated_at FROM training_session_segments a JOIN training_sessions s ON s.id=a.session_id JOIN scoped_plans p ON p.id=s.plan_id UNION ALL SELECT 'BLOCK',b.id,s.plan_id,b.updated_at FROM training_segment_blocks b JOIN training_session_segments a ON a.id=b.segment_id JOIN training_sessions s ON s.id=a.session_id JOIN scoped_plans p ON p.id=s.plan_id), selection AS (SELECT COALESCE(sqlc.arg(event_ids)::uuid[],'{}'::uuid[]) AS ids), eligible AS MATERIALIZED (SELECT event.id FROM training_copy_events event CROSS JOIN selection WHERE event.id=ANY(selection.ids) AND cardinality(selection.ids) BETWEEN 1 AND 65 AND event.copied_by_id=sqlc.arg(actor_id)::uuid AND ((event.source_kind='WEEK' AND event.destination_kind IN ('WEEK','SESSION')) OR (event.source_kind IN ('DAY','SESSION') AND event.destination_kind='SESSION') OR (event.source_kind IN ('BLOCK','SEGMENT') AND event.destination_kind=event.source_kind) OR (event.source_kind='ROUTINE' AND EXISTS(SELECT 1 FROM visible_routines r WHERE r.id=event.source_id AND r.kind::text=event.destination_kind))) AND EXISTS(SELECT 1 FROM objects destination WHERE destination.id=event.destination_id AND destination.kind=event.destination_kind AND destination.plan_id=sqlc.arg(target_plan_id)::uuid) AND ((sqlc.narg(source_plan_id)::uuid IS NOT NULL AND sqlc.narg(routine_id)::uuid IS NULL AND EXISTS(SELECT 1 FROM objects source WHERE source.plan_id=sqlc.narg(source_plan_id)::uuid AND source.id=event.source_id AND source.kind=CASE WHEN event.source_kind IN ('DAY','WEEK') AND event.destination_kind='SESSION' THEN 'SESSION' ELSE event.source_kind END )) OR (sqlc.narg(source_plan_id)::uuid IS NULL AND sqlc.narg(routine_id)::uuid IS NOT NULL AND event.source_kind='ROUTINE' AND EXISTS(SELECT 1 FROM visible_routines routine WHERE routine.id=sqlc.narg(routine_id)::uuid AND routine.id=event.source_id ))))
SELECT event.* FROM training_copy_events event JOIN eligible allowed ON allowed.id=event.id CROSS JOIN selection WHERE cardinality(selection.ids) BETWEEN 1 AND 65 AND cardinality(selection.ids)=(SELECT count(DISTINCT id) FROM unnest(selection.ids) chosen(id)) AND cardinality(selection.ids)=(SELECT count(*) FROM eligible) ORDER BY event.id;
